from pathlib import Path
import json,re,html
R=Path(__file__).resolve().parents[1];P=R/'public'
legal=(R/'scripts/content/legal.html').read_text()
(P/'images').mkdir(exist_ok=True)
rows=json.loads((R/'scripts/content/guides.json').read_text())
# Text pairs are the single content source for both rendered languages.
T=lambda en,fil:fil if lang=='fil' else en
def link(path):return ('/fil' if lang=='fil' else '')+('/' if path=='/' and lang!='fil' else '' if path=='/' else path)
def cta():return f'<a class="button" href="{link("/")}#ask">{T("Ask for help","Humingi ng tulong")}</a>'
def quote():return f'<a class="text-link" href="{link("/")}#website-quote">{T("Discuss a website","Pag-usapan ang website")}</a>'
def options(values):return ''.join(f'<option value="{html.escape(v)}">{html.escape(T(a,b))}</option>' for v,a,b in values)
def field(id,label,fil,name,type='text',required=False):
 return f'<div class="field"><label for="{id}">{T(label,fil)}</label><input id="{id}" name="{name}" type="{type}" {"required" if required else ""} maxlength="{254 if type=="email" else 80}" autocomplete="{name if name in ["name","email","tel"] else "off"}"><small class="field-error" id="{id}-error"></small></div>'
def form(kind):
 prefix={'inquiry':'inquiry','booking':'booking','project':'project'}[kind]
 f=f'<form id="{prefix}-form" class="request-form" method="post" action="/api/requests" data-kind="{kind}" novalidate><div class="form-row">'+field(prefix+'-name','Your name','Pangalan','name',required=True)+field(prefix+'-email','Email address','Email address','email','email',True)+'</div>'
 if kind=='project':
  values=[('New business website, landing page or portfolio','New website','Bagong website'),('Website redesign','Website redesign','Muling disenyo'),('Website content updates','Content updates','Pag-update ng nilalaman'),('Mobile layout or website troubleshooting','Website fixes','Pag-aayos ng website'),('Domain, contact form or basic search setup','Domain, forms or search setup','Domain, forms o search setup'),('Booking, payment or other integration','Integrations','Integrations'),('Business email or Microsoft 365 setup','Business email or Microsoft 365','Business email o Microsoft 365'),('Booking or inquiry form setup','Booking or inquiry forms','Booking o inquiry forms'),('Website care or ongoing updates','Website care','Pag-aalaga ng website'),('Other website project — review required','Other website project','Ibang website project')]
  f+=f'<div class="field"><label for="project-type">{T("Project type","Uri ng proyekto")}</label><select id="project-type" name="projectType" required><option value="">{T("Choose a project","Pumili ng proyekto")}</option>{options(values)}</select><small id="project-type-error" class="field-error"></small></div>'+field('project-url','Existing website (optional)','Kasalukuyang website (opsyonal)','siteUrl','url')+field('project-timing','Preferred timeframe (optional)','Gustong iskedyul (opsyonal)','timeframe')
 else:
  values=[('Windows laptop','Windows laptop','Windows laptop'),('Windows desktop','Windows desktop','Windows desktop'),('Apple Mac','Apple Mac','Apple Mac'),('iPhone or iPad','iPhone or iPad','iPhone o iPad'),('Printer/scanner','Printer or scanner','Printer o scanner'),('Other','Other','Iba')]
  f+=f'<div class="field"><label for="{prefix}-device">{T("Your device","Device mo")}</label><select id="{prefix}-device" name="device" required><option value="">{T("Choose a device","Pumili ng device")}</option>{options(values)}</select><small class="field-error" id="{prefix}-device-error"></small></div><input type="hidden" name="category" value="General computer problem">'
 f+=f'<div class="field"><label for="{prefix}-description">{T("What would you like help with?","Ano ang kailangan mong tulong?")}</label><textarea id="{prefix}-description" name="description" rows="4" required minlength="10" maxlength="2000"></textarea><small class="field-error" id="{prefix}-description-error"></small></div>'
 if kind=='booking':
  f+='<input type="hidden" name="method" value="Remote">'+field('booking-date','Preferred date','Gustong petsa','date','date',True)+field('booking-window','Preferred time window (Eastern time)','Gustong oras (Eastern time)','window',required=True)+field('booking-phone','Phone (optional)','Telepono (opsyonal)','phone','tel')
  f+=f'<label class="check"><input type="checkbox" name="consent" id="booking-consent" required>{T("I understand this is an appointment request, subject to review and the service terms.","Nauunawaan kong kahilingan pa lamang ito, sasailalim sa pagsusuri at sa mga tuntunin ng serbisyo.")}</label><small class="field-error" id="booking-consent-error"></small>'
 f+=f'<div class="honeypot" aria-hidden="true"><label for="{prefix}-website">Leave empty</label><input id="{prefix}-website" name="website" tabindex="-1" autocomplete="off"></div><p class="small">{T("Keep passwords, payment details and private files out of your message. Your details are used to respond to your request.","Huwag ilagay ang passwords, detalye ng bayad o pribadong files. Gagamitin ang detalye mo para sagutin ang request.")} <button type="button" class="inline-link" data-dialog="privacy-dialog">{T("Privacy","Privacy")}</button> · <button type="button" class="inline-link" data-dialog="terms-dialog">{T("Service terms (English)","Mga tuntunin (English)")}</button></p><button class="button" type="submit" disabled>{T("Send inquiry","Ipadala ang inquiry")}</button><p class="form-status" role="status" tabindex="-1"></p><noscript><p>{T("Please email your request.","I-email ang iyong request.")}</p></noscript></form>'
 return f

def page(slug,title,desc,body):
 filename=('fil-' if lang=='fil' else '')+('index' if slug=='/' else slug.strip('/').replace('/','-'))+'.html'
 path=link(slug);alternate=('/fil' if lang=='en' else '')+('' if slug=='/' else slug)
 if not alternate:alternate='/'
 nav=''.join(f'<a href="{link(p)}">{T(a,b)}</a>' for p,a,b in [('/remote-tech-support','Tech help','Tech help'),('/website-design','Websites','Mga website'),('/clinic','Tech Clinic','Tech Clinic'),('/resources','Resources','Mga gabay'),('/journal','Journal','Mga artikulo')])
 controls=f'''<details class="preferences"><summary>{T('Make yourself comfortable','Gawing komportable ang pagbasa')}</summary><div class="preference-fields"><label>{T('Season & holiday','Season at holiday')}<select id="theme-choice">{options([(v,v.replace('-',' ').title(),{'auto':'Awtomatiko','spring':'Tagsibol','summer':'Tag-araw','autumn':'Taglagas','winter':'Taglamig'}.get(v,v.replace('-',' ').title())) for v in ['auto','spring','summer','autumn','winter','christmas','new-year','valentine','easter','canada-day','halloween','thanksgiving']])}</select></label><label>{T('Appearance','Hitsura')}<select id="appearance">{options([('system','System','System'),('light','Light','Maliwanag'),('dark','Dark','Madilim')])}</select></label><label class="check"><input id="calm" type="checkbox">{T('Calm mode','Calm mode')}</label><label class="check"><input id="large-text" type="checkbox">{T('Larger text','Mas malaking teksto')}</label></div></details>'''
 header=f'<header class="masthead"><a class="wordmark" href="{link("/")}">Online Technical Help<span>{T("The living tech studio","Ang living tech studio")}</span></a><nav aria-label="{T("Main navigation","Pangunahing nabigasyon")}">{nav}</nav><a class="language" href="{alternate}" lang="{ "fil" if lang=="en" else "en-CA"}">{T("Filipino","English")}</a></header>'
 footer=f'<footer><div><a class="wordmark" href="{link("/")}">Online Technical Help</a><p>{T("Based in Hamilton, Ontario. All services are remote.","Nakabase sa Hamilton, Ontario. Lahat ng serbisyo ay remote.")}</p></div><nav aria-label="Footer">'+''.join(f'<a href="{link(p)}">{T(a,b)}</a>' for p,a,b in [('/about','About','Tungkol'),('/contact','Contact','Makipag-ugnayan'),('/portfolio','Work','Mga gawa'),('/business-solutions','Business setup','Business setup'),('/website-maintenance','Website care','Website care')])+f'<a href="{link("/")}#privacy">Privacy</a><a href="{link("/")}#terms">{T("Service terms","Mga tuntunin")}</a></nav><p class="small">{T("Photography by","Larawan ni")} <a href="https://unsplash.com/photos/cactus-beside-laptop-p-0lWFknspg">Scott Webb / Unsplash</a>. <a href="https://eccc-msc.github.io/open-data/licence/readme_en/">{T("Weather data: Environment and Climate Change Canada","Datos ng panahon: Environment and Climate Change Canada")}</a>.</p><button id="surprise" class="inline-link">{T("A little useful surprise","Isang kapaki-pakinabang na sorpresa")}</button><p id="tip" role="status"></p></footer>'
 dialogs=''
 if slug=='/':
  for kind,name,fil in [('booking','Request an appointment','Humiling ng appointment'),('project','Discuss a website or business project','Pag-usapan ang website o business project')]:
   dialogs+=f'<dialog id="{kind}-dialog" aria-labelledby="{kind}-title"><button class="close-dialog" aria-label="{T("Close","Isara")}">×</button><h2 id="{kind}-title">{T(name,fil)}</h2><p>{T("I review the scope and availability before confirming any work or appointment.","Susuriin ko ang saklaw at availability bago kumpirmahin ang trabaho o appointment.")}</p>'+form(kind)+'</dialog>'
  dialogs+=legal.replace('<dialog ', '<dialog lang="en-CA" ')
 htmltext=f'<!doctype html><html lang="{ "fil" if lang=="fil" else "en-CA"}"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><title>{html.escape(title)} | Online Technical Help</title><meta name="description" content="{html.escape(desc)}"><meta property="og:title" content="{html.escape(title)}"><meta property="og:description" content="{html.escape(desc)}"><meta property="og:type" content="website"><meta name="twitter:card" content="summary"><!-- SITE_METADATA --><link rel="icon" href="/favicon.svg"><link rel="stylesheet" href="/studio.css"><script type="module" src="/studio.js"></script></head><body><a class="skip-link" href="#main">{T("Skip to content","Pumunta sa nilalaman")}</a><div class="shell">{header}<div class="utility">{controls}<span id="weather" class="small">{T("A little atmosphere from Hamilton","Kaunting himig mula sa Hamilton")}</span></div><main id="main">{body}</main>{footer}</div>{dialogs}</body></html>'
 (P/filename).write_text(htmltext)
 routes.append({'path':path,'file':filename})

def intro(kicker,title,body):return f'<section class="intro"><p class="eyebrow">{kicker}</p><h1>{title}</h1><p class="lead">{body}</p></section>'
def comparison():return f'''<section class="comparison-section"><div><p class="eyebrow">{T('A website, reconsidered','Muling pagdisenyo ng website')}</p><h2>{T('Small changes.<br>A clearer invitation.','Maliit na pagbabago.<br>Mas malinaw na paanyaya.')}</h2><p>{T('An original cleaning-business concept. Move the divider to compare a crowded layout with a focused service page.','Isang orihinal na konsepto para sa cleaning business. Igalaw ang divider para ihambing ang masikip na layout sa mas malinaw na service page.')}</p><p class="small">{T('Design demonstration. Client results have not been measured.','Demonstrasyon ng disenyo. Wala pang nasusukat na resulta mula sa client.')}</p></div><div><div class="comparison"><img src="/images/before.png" width="1000" height="680" alt="{T('Before concept with crowded navigation and small service text','Konsepto bago ayusin, na may masikip na nabigasyon at maliit na teksto')}"><div class="comparison-after"><img src="/images/after.png" width="1000" height="680" alt="{T('After concept with a clear service headline and quote button','Konsepto matapos ayusin, na may malinaw na headline at quote button')}"></div></div><label for="compare">{T('Before / after comparison','Paghahambing ng bago at pagkatapos')}</label><input id="compare" type="range" min="0" max="100" value="50" aria-valuetext="{T("50% after","50% pagkatapos")}"></div></section>'''

routes=[]
for lang in ['en','fil']:
 home=f'''<section class="hero"><div><p class="eyebrow">{T('Independent tech help · Hamilton, Canada','Independiyenteng tech help · Hamilton, Canada')}</p><h1>{T('A little clarity.<br>A better day.','Mas malinaw.<br>Mas magaan ang araw.')}</h1><p class="lead">{T('Patient help with everyday technology. Thoughtful websites for small businesses. Work directly with an independent IT professional, wherever you feel at home.','Matiyagang tulong sa araw-araw na teknolohiya. Maingat na disenyo ng website para sa maliliit na negosyo. Direktang makipagtrabaho sa isang independiyenteng IT professional, saan ka man komportable.')}</p><div class="actions">{cta()}{quote()}</div><p class="small">{T('Remote support from $40 CAD. Scope and price agreed before work.','Remote support mula $40 CAD. Pagkakasunduan ang saklaw at presyo bago magsimula.')}</p></div><figure class="hero-photo"><img src="/images/studio.jpg" width="1400" height="933" fetchpriority="high" alt="{T('A quiet home workspace with a laptop and cactus','Tahimik na workspace sa bahay na may laptop at cactus')}"><div class="season-decoration" aria-hidden="true"><i></i><i></i><i></i></div><figcaption id="edition">{T('A studio for every season','Isang studio sa bawat season')}</figcaption></figure></section>
 <section class="service-list" id="services"><h2>{T('What can I make easier?','Ano ang maitutulong ko?')}</h2>'''
 for path,h,hf,d,df in [('/remote-tech-support','Everyday tech, explained.','Araw-araw na tech, ipinaliliwanag.','Windows, Mac, email, OneDrive and printer connections. Start with what is happening.','Windows, Mac, email, OneDrive at printer connections. Ikuwento ang nangyayari.'),('/website-design','A website that feels like you.','Website na bagay sa iyo.','New websites, redesigns and considered updates for independent businesses.','Bagong website, muling disenyo at maingat na updates para sa negosyo.'),('/business-solutions','A smoother working day.','Mas maayos na araw ng trabaho.','Business email, booking forms and practical tools, scoped around your workflow.','Business email, booking forms at praktikal na tools ayon sa daloy ng trabaho.')]:
  home+=f'<a class="service-row" href="{link(path)}"><h3>{T(h,hf)}</h3><p>{T(d,df)}</p></a>'
 home+=f'''</section><aside class="campaign"><p class="eyebrow">{T('In season','Ngayong season')}</p><p id="campaign-text">{T('A good time to give your everyday technology some attention.','Panahon para bigyang-pansin ang ginagamit mong teknolohiya.')}</p>{cta()}</aside><section class="clinic-teaser"><p class="eyebrow">The Digital Tech Clinic</p><h2>{T('Start with a small,<br>safe next step.','Magsimula sa maliit<br>at ligtas na hakbang.')}</h2><p>{T('Tell the clinic what is happening. Get a short, beginner-friendly checklist, then decide whether you need personal help.','Sabihin sa clinic ang nangyayari. Kumuha ng maikling checklist, saka magpasya kung kailangan ng personal na tulong.')}</p><a class="button" href="{link('/clinic')}">{T('Visit the Tech Clinic','Bisitahin ang Tech Clinic')}</a></section><section class="founder"><p class="eyebrow">{T('A note from the person helping you','Mensahe mula sa tutulong sa iyo')}</p><h2>{T('You can ask the “simple” question.','Puwedeng itanong ang “simpleng” tanong.')}</h2><p>{T('I know how much time a small technology problem can take out of your day. My approach is to listen, explain the options clearly and work through the next step with you.','Alam kong nakauubos ng oras ang kahit maliit na problema sa teknolohiya. Makikinig ako, malinaw na ipaliliwanag ang mga pagpipilian at tutulungan ka sa susunod na hakbang.')}</p><p>{T('I have a bachelor’s degree in Information Technology, a Software Support diploma and professional experience with Windows, Mac and Microsoft 365 environments. You work directly with me from the first question to the final handover.','May bachelor’s degree ako sa Information Technology, Software Support diploma at propesyonal na karanasan sa Windows, Mac at Microsoft 365. Ako mismo ang kausap mo mula unang tanong hanggang handover.')}</p></section>'''
 home+=f'<section id="how-it-works"><h2>{T("Help, on your terms.","Tulong ayon sa pangangailangan mo.")}</h2><div class="steps">'
 for a,b,c,d in [('Before we meet','Bago tayo magkita','Describe your issue. I review remote suitability, then agree on scope, price and a time with you.','Ilarawan ang problema. Susuriin ko kung angkop ang remote help bago pagkasunduan ang saklaw, presyo at oras.'),('While we work','Habang nagtatrabaho','You approve any remote connection, watch the session and can end it. Enter your own passwords privately.','Ikaw ang mag-aapruba ng remote connection, makakapanood at makakapagtapos nito. Ikaw ang pribadong maglalagay ng passwords.'),('Before we finish','Bago matapos','We check the agreed work together and review any next steps. Ongoing access is not kept by default.','Sabay nating susuriin ang napagkasunduang trabaho at susunod na hakbang. Walang pinananatiling access bilang default.')]:home+=f'<article><h3>{T(a,b)}</h3><p>{T(c,d)}</p></article>'
 home+=f'</div></section><section id="pricing" class="pricing"><h2>{T("Clear scope. Written quotes.","Malinaw na saklaw. Nakasulat na quote.")}</h2><div class="price-lines"><p>{T("Remote tech help","Remote tech help")} <strong>{T("from $40 CAD","mula $40 CAD")}</strong></p><p>{T("New computer setup","Pag-setup ng bagong computer")} <strong>{T("from $85 CAD","mula $85 CAD")}</strong></p><p>{T("Setup with file transfer","Setup at paglipat ng files")} <strong>{T("from $110 CAD","mula $110 CAD")}</strong></p><p>{T("Website projects","Website projects")} <strong>{T("By written quote","Ayon sa nakasulat na quote")}</strong></p></div><p>{T("A defined task keeps its quoted price if it finishes early. Uncertain problems are scoped as diagnostic work. Additional work needs your approval. Payment timing, taxes and third-party costs are agreed in the quote.","Mananatili ang napagkasunduang presyo kahit maagang matapos ang tiyak na gawain. Ang hindi malinaw na problema ay sasaklawin bilang diagnostic work. Kailangan ang pahintulot mo sa dagdag na trabaho. Nasa quote ang bayad, buwis at third-party costs.")}</p>{cta()}</section>'
 home+=comparison()+f'<section><h2>{T("A few things worth keeping.","Mga gabay na magandang itabi.")}</h2><div class="resource-list">'+''.join(f'<a href="/guides/{r[0]}-{lang}.pdf" download>{r[1 if lang=="en" else 2]} <small>PDF</small></a>' for r in rows[:3])+f'</div><a href="{link("/resources")}">{T("Explore all ten free guides","Tingnan ang sampung libreng gabay")}</a></section>'
 faqs=[('Can you help remotely?','Maaari ba ang remote help?','Many software and setup issues can be assessed remotely when you have a working connection. Physical damage, failing drives and complete internet outages may need a local provider.','Maraming software at setup issues ang masusuri nang remote kung may internet. Maaaring mangailangan ng lokal na provider ang pisikal na sira, pumapalyang drive o lubos na pagkawala ng internet.'),('What if the problem cannot be fixed?','Paano kung hindi maayos?','The written quote explains the diagnostic scope and fee before work. If a different service is needed, we discuss the next step.','Ipinaliliwanag sa nakasulat na quote ang diagnostic scope at bayad bago magsimula. Pag-uusapan ang susunod na hakbang kung ibang serbisyo ang kailangan.'),('Is an inquiry a booking?','Booking na ba ang inquiry?','I review your request and availability first. An appointment or project starts only after we agree in writing.','Susuriin ko muna ang request at availability. Kailangan muna ang nakasulat na kasunduan bago ang appointment o proyekto.')]
 home+='<section id="faq"><h2>'+T('Good questions.','Magagandang tanong.')+'</h2>'+''.join(f'<details><summary>{T(a,b)}</summary><p>{T(c,d)}</p></details>' for a,b,c,d in faqs)+'</section>'
 home+=f'<section id="ask" class="inquiry"><div><p class="eyebrow">{T("Start with a question","Magsimula sa tanong")}</p><h2>{T("Tell me what is happening.","Ikuwento ang nangyayari.")}</h2><p>{T("A few sentences are enough. Messages are reviewed personally and are not monitored continuously.","Sapat na ang ilang pangungusap. Personal na sinusuri ang mensahe at hindi ito palaging minomonitor.")}</p><button class="inline-link" data-dialog="booking-dialog">{T("Prefer to request an appointment?","Gustong humiling ng appointment?")}</button><p><a href="mailto:techspecialistsupport@gmail.com">techspecialistsupport@gmail.com</a></p></div>{form("inquiry")}</section>'
 page('/',T('Patient Remote Tech Help & Thoughtful Websites','Matiyagang Tech Help at Maingat na Website Design'),T('Remote tech support from Hamilton, Canada. Personal computer help, website design, free guides and the Digital Tech Clinic.','Remote tech support mula Hamilton, Canada. Personal na computer help, website design, libreng gabay at Digital Tech Clinic.'),home)
 # Service pages share the same style and preferences.
 services=[('/remote-tech-support','Remote tech support','Remote tech support','Everyday technology, with a little patience.','Araw-araw na teknolohiya, nang may tiyaga.','Help with Windows, Mac, Outlook, OneDrive, printer connections, software setup and new computers. Start by describing the problem so I can assess whether remote support is suitable.','Tulong sa Windows, Mac, Outlook, OneDrive, printer connections, software setup at bagong computer. Ilarawan muna ang problema para masuri kung angkop ang remote support.'),('/website-design','Website design','Website design','A considered home for your business.','Maingat na tahanan ng negosyo mo online.','One-page sites, small business websites, portfolios and redesigns. We agree on content, pages, revisions, testing and handover in a written quote. Hosting and paid tools are itemized separately.','One-page sites, website ng negosyo, portfolio at muling disenyo. Pagkakasunduan sa nakasulat na quote ang content, pages, revisions, testing at handover. Hiwalay na nakalista ang hosting at paid tools.'),('/website-maintenance','Website care','Website care','Keep your website useful.','Panatilihing kapaki-pakinabang ang website.','Request content changes, mobile layout improvements or a review of a form that is not working. Ongoing care is discussed individually. Monthly plans are not currently available to purchase.','Humiling ng content changes, pagbuti ng mobile layout o pagsusuri ng form na hindi gumagana. Hiwalay na pinag-uusapan ang patuloy na pag-aalaga. Wala pang monthly plan na mabibili.'),('/business-solutions','Business digital setup','Business digital setup','Less admin friction. More room to work.','Mas maayos na proseso. Mas maraming oras sa trabaho.','Business email, Microsoft 365, inquiry forms and booking tools. We review the provider and workflow before quoting configuration, testing and handover. Subscription costs are separate.','Business email, Microsoft 365, inquiry forms at booking tools. Susuriin ang provider at workflow bago mag-quote para sa configuration, testing at handover. Hiwalay ang subscription costs.'),('/contact','Contact','Makipag-ugnayan','A question is a good beginning.','Magandang simula ang tanong.','Send a short description of your device or business goal. I will review feasibility and availability, then propose a scope and price.','Magpadala ng maikling paglalarawan ng device o layunin ng negosyo. Susuriin ko ang feasibility at availability bago magmungkahi ng saklaw at presyo.'),('/about','About the studio','Tungkol sa studio','A real person, from question to handover.','Tunay na kausap mula tanong hanggang handover.','I am an independent IT professional based in Hamilton. I hold a bachelor’s degree in Information Technology and a Software Support diploma, with professional experience supporting Windows, Mac and Microsoft 365 workflows. My aim is to make the next step understandable.','Isa akong independiyenteng IT professional sa Hamilton. May bachelor’s degree ako sa Information Technology at Software Support diploma, at propesyonal na karanasan sa Windows, Mac at Microsoft 365. Layunin kong gawing malinaw ang susunod na hakbang.')]
 for slug,a,b,c,d,e,f in services:
  body=intro(T(a,b),T(c,d),T(e,f))+f'<div class="actions">{cta()}{quote()}</div>'
  if slug=='/remote-tech-support':body+=f'<section><h2>{T("Could remote help fit?","Angkop ba ang remote help?")}</h2><p>{T("A working internet connection and authorization to use the device are needed. If there is physical damage, smoke, a swollen battery or a failing drive, stop using the affected equipment and seek suitable local help.","Kailangan ng internet at pahintulot sa device. Kung may pisikal na sira, usok, namamagang baterya o pumapalyang drive, itigil ang paggamit at humingi ng angkop na lokal na tulong.")}</p><a href="{link("/clinic")}">{T("Use the suitability check in the clinic","Gamitin ang suitability check sa clinic")}</a></section>'
  if slug=='/about':body+=f'<section class="founder"><h2>{T("Ask in your own words.","Magtanong sa sarili mong pananalita.")}</h2><p>{T("You do not need to know the technical term. Tell me what you were trying to do and what happened instead. We can work from there.","Hindi kailangang alam mo ang technical term. Sabihin kung ano ang sinusubukan mong gawin at kung ano ang nangyari. Doon tayo magsisimula.")}</p></section>'
  page(slug,T(a,b),T(e,f),body)
 page('/portfolio',T('Website design concepts','Mga konsepto ng website'),T('An accessible before-and-after design comparison.','Accessible na paghahambing ng disenyo.'),intro(T('Selected concepts','Mga konsepto'),'Websites, reconsidered.' if lang=='en' else 'Mga website, muling pinag-isipan.',T('Explore a layout study for a fictional cleaning business.','Tingnan ang pag-aaral ng layout para sa kathang-isip na cleaning business.'))+comparison()+quote())
 resources=intro(T('The resource shelf','Mga gabay'),'A little knowledge to keep.' if lang=='en' else 'Kaalamang magandang itabi.',T('Ten practical checklists. Free to read, print and download. No email address needed.','Sampung praktikal na checklist. Libreng basahin, i-print at i-download. Walang kailangang email address.'))+'<div class="resource-list">'
 for r in rows:resources+=f'<article><h2>{r[1 if lang=="en" else 2]}</h2><p>{r[3 if lang=="en" else 4].rstrip(".")}.</p><a href="/guides/{r[0]}-{lang}.pdf" download>{T("Download PDF","I-download ang PDF")}</a></article>'
