 for a,b in [('I have a recent backup I can open.','May bago akong backup na nabubuksan.'),('I use unique account passwords.','Natatangi ang passwords ng accounts ko.'),('I install updates through official settings.','Nag-i-install ako ng updates sa opisyal na settings.')]:resources+=f'<label class="check"><input type="checkbox">{T(a,b)}</label>'
